import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';import {guarded} from './run-canonical-body-learning-guarded-20261025.mjs';
const stage='F:/VisibleMedicine/staging/20261025-dental-ct-native',prep=json(stage+'/PREPARATION.json'),site=prep.atlas,dir=stage+'/checks/focused-attempt-2';function verify(){const mutable=new Map(json(stage+'/STATE.json').mutable.map(r=>[r.path,r]));for(const old of prep.sourceRows){const r=mutable.get(old.path)??old;assert.equal(hash(site+'/'+r.path),r.sha256,r.path);}for(const r of prep.publicRows)assert.equal(hash(site+'/'+r.path),r.sha256,r.path);}
